import React, { useState, useEffect } from 'react';

const CoursePlayer = () => {
  // 1. Simulation des données reçues de l'API après vérification des droits côté serveur
  const [courseData, setCourseData] = useState({
    id: "hacking-ethique",
    title: "Hacking Éthique & Pentest : Les Fondations",
    hasPdfResume: true, // Le serveur confirme la présence du fichier
    hasPdfTp: true,     // Le serveur confirme la présence du fichier
    userProgress: {
      lastViewedLessonId: 2, // L'étudiant s'était arrêté à la leçon 2
      completedLessons: [1]   // La leçon 1 est marquée comme terminée
    },
    lessons: [
      { id: 1, title: "01. Introduction au cours et au programme", duration: "12:45" },
      { id: 2, title: "02. Configuration du lab de test pfSense", duration: "24:15" },
      { id: 3, title: "03. Phase de reconnaissance avancée avec Nmap", duration: "18:30" },
      { id: 4, title: "04. Exploitation de failles et élévation de privilèges", duration: "32:10" }
    ]
  });

  // États de navigation
  const [currentLessonId, setCurrentLessonId] = useState(courseData.userProgress.lastViewedLessonId);
  const [completedLessons, setCompletedLessons] = useState(courseData.userProgress.completedLessons);
  const [videoUrl, setVideoUrl] = useState('');
  const [isLoadingVideo, setIsLoadingVideo] = useState(false);
  const [accessDenied, setAccessDenied] = useState(false);

  // Trouver l'objet de la leçon actuelle
  const currentLesson = courseData.lessons.find(l => l.id === currentLessonId);

  // 2. SIMULATION DU CONTRÔLE SERVEUR (Sécurité Vidéo)
  // À chaque changement de leçon, on demande l'URL sécurisée au serveur
  useEffect(() => {
    const fetchSecureVideo = async () => {
      setIsLoadingVideo(true);
      setAccessDenied(false);
      
      try {
        // En production, ce serait : fetch(`/api/lessons/${currentLessonId}`)
        // Le serveur vérifie le JWT dans les en-têtes et la table "inscriptions"
        const simulateServerCheck = true; // Simule un statut payé valide

        if (simulateServerCheck) {
          // Le serveur renvoie un lien sécurisé ou temporaire
          setVideoUrl(`https://secure-stream.avalon-secure.com/vod/lesson-${currentLessonId}.mp4`);
          
          // Sauvegarde automatique de la progression côté serveur (lastViewedLessonId)
          console.log(`[API Server] Progression enregistrée : Leçon ${currentLessonId}`);
        } else {
          // Si la vérification serveur échoue (ex: jeton expiré, non payé)
          setAccessDenied(true);
        }
      } catch (err) {
        setAccessDenied(true);
      } finally {
        setIsLoadingVideo(false);
      }
    };

    fetchSecureVideo();
  }, [currentLessonId]);

  // 3. SIMULATION DU TÉLÉCHARGEMENT SÉCURISÉ DES PDF (Flux Blob)
  const handleSecureDownload = async (type) => {
    console.log(`[API Server] Requête vers /api/courses/${courseData.id}/download-${type}`);
    alert(`[Sécurité Serveur] Jeton d'accès vérifié dans la table "inscriptions".\nLe flux binaire (Blob) du PDF ${type.toUpperCase()} va être injecté directement sur votre PC.`);
  };

  // Gestion de la validation d'une leçon et passage à la suivante
  const handleNextLesson = () => {
    // Ajouter la leçon actuelle aux leçons terminées si ce n'est pas déjà fait
    if (!completedLessons.includes(currentLessonId)) {
      const updatedProgress = [...completedLessons, currentLessonId];
      setCompletedLessons(updatedProgress);
      // En production, envoyer la mise à jour au serveur ici via POST /api/progress
    }

    // Trouver l'index de la leçon suivante
    const currentIndex = courseData.lessons.findIndex(l => l.id === currentLessonId);
    if (currentIndex < courseData.lessons.length - 1) {
      setCurrentLessonId(courseData.lessons[currentIndex + 1].id);
    }
  };

  // Calcul mathématique exact de la barre de progression
  const progressPercentage = Math.round((completedLessons.length / courseData.lessons.length) * 100);

  return (
    <div className="min-h-screen bg-[#020617] text-slate-200 font-sans flex flex-col md:flex-row antialiased">
      
      {/* PANNEAU LATÉRAL : PROGRAMME & PROGRESSION */}
      <aside className="w-full md:w-80 border-r border-slate-900 bg-[#020617] flex flex-col shrink-0">
        
        {/* Entête du cours */}
        <div className="p-6 border-b border-slate-900">
          <a href="/" className="text-[10px] font-mono text-blue-500 hover:underline tracking-wider uppercase mb-2 block">
            ← Retour à l'infrastructure
          </a>
          <h2 className="text-sm font-bold text-white uppercase tracking-wide leading-tight">
            {courseData.title}
          </h2>
        </div>

        {/* SECTION BARRE DE PROGRESSION */}
        <div className="p-6 border-b border-slate-900 bg-slate-950/40 space-y-2">
          <div className="flex justify-between items-center text-xs font-mono">
            <span className="text-slate-400 uppercase tracking-wider">Progression</span>
            <span className="text-blue-400 font-bold">{completedLessons.length} / {courseData.lessons.length} Modules</span>
          </div>
          <div className="w-full bg-slate-900 h-1.5 rounded-full overflow-hidden border border-slate-800">
            <div 
              className="bg-gradient-to-r from-blue-600 to-cyan-500 h-full rounded-full transition-all duration-500 shadow-[0_0_8px_#3b82f6]" 
              style={{ width: `${progressPercentage}%` }}
            ></div>
          </div>
          <div className="text-[10px] text-slate-500 font-mono text-right">{progressPercentage}% complété</div>
        </div>

        {/* LISTE DES 1000 VIDÉOS OPTIONNELLES */}
        <div className="flex-1 overflow-y-auto p-4 space-y-2 custom-scrollbar">
          <span className="text-[10px] font-mono text-slate-600 uppercase tracking-widest px-2 block mb-2">Index du Programme</span>
          
          {courseData.lessons.map((lesson) => {
            const isCurrent = lesson.id === currentLessonId;
            const isCompleted = completedLessons.includes(lesson.id);

            return (
              <button
                key={lesson.id}
                onClick={() => setCurrentLessonId(lesson.id)}
                className={`w-full text-left p-3.5 rounded-lg border text-xs font-medium transition-all duration-200 flex justify-between items-center group
                  ${isCurrent 
                    ? 'bg-blue-500/5 border-blue-500 text-blue-400 shadow-[0_0_15px_rgba(59,130,246,0.1)]' 
                    : 'bg-transparent border-slate-950 text-slate-400 hover:border-slate-800 hover:text-white'}`}
              >
                <div className="flex items-center gap-3 max-w-[80%]">
                  {isCompleted ? (
                    <span className="text-emerald-400 font-bold font-mono shrink-0">✓</span>
                  ) : (
                    <span className={`font-mono text-[10px] shrink-0 ${isCurrent ? 'text-blue-400' : 'text-slate-600'}`}>
                      {isCurrent ? '▶' : '•'}
                    </span>
                  )}
                  <span className="truncate tracking-wide">{lesson.title}</span>
                </div>
                {/* Affichage de la durée dans la structure */}
                <span className="text-[10px] font-mono text-slate-600 group-hover:text-slate-400 transition-colors">
                  {lesson.duration}
                </span>
              </button>
            );
          })}
        </div>
      </aside>

      {/* ZONE PRINCIPALE : LECTEUR ET RESSOURCES */}
      <main className="flex-1 bg-[#020617] p-8 flex flex-col justify-between overflow-y-auto">
        
        {/* En-tête de la leçon actuelle */}
        <div className="mb-6 flex justify-between items-start border-b border-slate-900/60 pb-6">
          <div className="space-y-1">
            <span className="text-[9px] font-mono text-slate-500 uppercase tracking-widest">// Session Active</span>
            <h1 className="text-xl font-bold text-white tracking-tight">{currentLesson?.title}</h1>
          </div>
          <div className="bg-slate-950 border border-slate-800 px-3 py-1 rounded font-mono text-[10px] text-slate-400">
            ID: SEC-{currentLessonId}
          </div>
        </div>

        {/* ESPACE LECTEUR VIDÉO PROTÉGÉ */}
        <div className="relative aspect-video w-full bg-slate-950 rounded-xl border border-slate-900 flex items-center justify-center overflow-hidden shadow-2xl group max-w-5xl mx-auto">
          {accessDenied ? (
            /* Écran 403 Forbidden Server */
            <div className="text-center space-y-3 p-6 z-10 font-mono">
              <div className="w-12 h-12 rounded-full bg-red-500/10 border border-red-500/30 flex items-center justify-center text-red-400 text-lg mx-auto animate-pulse">✕</div>
              <h3 className="text-sm font-bold text-red-400 uppercase tracking-wider">403 FORBIDDEN</h3>
              <p className="text-xs text-slate-500 max-w-sm font-light">Validation serveur échouée. Token invalide ou aucun reçu d'achat trouvé pour ce module d'information.</p>
            </div>
          ) : isLoadingVideo ? (
            <div className="text-center font-mono text-xs text-slate-500 uppercase tracking-widest animate-pulse">
              Vérification des droits et chiffrement du flux...
            </div>
          ) : (
            /* Le lecteur n'est alimenté que si le serveur a retourné l'URL */
            <video 
              key={videoUrl}
              src={videoUrl} 
              controls 
              controlsList="nodownload" // Bloque le clic droit / bouton télécharger natif du navigateur
              className="w-full h-full object-cover"
              autoPlay
            />
          )}
          <div className="absolute top-4 left-4 pointer-events-none bg-slate-950/80 border border-slate-800/60 px-2 py-1 rounded font-mono text-[8px] text-slate-500 tracking-widest uppercase opacity-0 group-hover:opacity-100 transition-opacity">
            Flux Sécurisé Avalon_Core
          </div>
        </div>

        {/* NAVIGATION & DOCUMENTS OPTIONNELS (Bas de page) */}
        <div className="mt-8 max-w-5xl w-full mx-auto space-y-8">
          
          {/* Ligne d'action : BOUTON SUIVANT */}
          <div className="flex justify-end border-b border-slate-900 pb-8">
            <button
              onClick={handleNextLesson}
              disabled={courseData.lessons.findIndex(l => l.id === currentLessonId) === courseData.lessons.length - 1}
              className="bg-white hover:bg-blue-600 text-slate-950 hover:text-white px-8 py-3.5 rounded-lg text-xs font-mono font-bold tracking-widest uppercase transition-all duration-300 disabled:bg-slate-900 disabled:text-slate-600 disabled:cursor-not-allowed shadow-md"
            >
              Leçon Suivante ➔
            </button>
          </div>

          {/* ZONE DE TÉLÉCHARGEMENT SÉCURISÉ DES RESSOURCES (Conditionnelle) */}
          {(courseData.hasPdfResume || courseData.hasPdfTp) && (
            <div className="space-y-4">
              <div className="flex items-center gap-2">
                <div className="w-1 h-3 bg-blue-500 rounded-full"></div>
                <h3 className="text-xs font-bold text-white uppercase tracking-wider">Ressources Téléchargeables en Autonomie</h3>
              </div>
              
              <div className="grid sm:grid-cols-2 gap-4">
                
                {/* Fichier Résumé : S'affiche uniquement si présent */}
                {courseData.hasPdfResume && (
                  <div className="bg-slate-950/40 border border-slate-900 rounded-xl p-5 flex justify-between items-center hover:border-slate-800 transition">
                    <div className="space-y-1 max-w-[70%]">
                      <p className="text-xs font-bold text-white tracking-wide truncate">Fiche Synthèse Complète</p>
                      <p className="text-[10px] text-slate-500 font-light leading-snug">Résumé global rédigé par le professeur pour révision locale.</p>
                    </div>
                    <button
                      onClick={() => handleSecureDownload('resume')}
                      className="bg-slate-900 border border-slate-800 hover:border-blue-500 hover:bg-blue-500/5 text-slate-300 hover:text-blue-400 px-4 py-2 rounded text-[10px] font-mono font-bold uppercase tracking-wider transition-all duration-200 shrink-0"
                    >
                        Télécharger
                    </button>
                  </div>
                )}

                {/* Fichier TP : S'affiche uniquement si présent */}
                {courseData.hasPdfTp && (
                  <div className="bg-slate-950/40 border border-slate-900 rounded-xl p-5 flex justify-between items-center hover:border-slate-800 transition">
                    <div className="space-y-1 max-w-[70%]">
                      <p className="text-xs font-bold text-white tracking-wide truncate">Travaux Pratiques Empiriques</p>
                      <p className="text-[10px] text-slate-500 font-light leading-snug">Consignes de manipulation à réaliser sur votre PC pour votre GitHub.</p>
                    </div>
                    <button
                      onClick={() => handleSecureDownload('tp')}
                      className="bg-slate-900 border border-slate-800 hover:border-blue-500 hover:bg-blue-500/5 text-slate-300 hover:text-blue-400 px-4 py-2 rounded text-[10px] font-mono font-bold uppercase tracking-wider transition-all duration-200 shrink-0"
                    >
                      Télécharger
                    </button>
                  </div>
                )}

              </div>
            </div>
          )}

        </div>
      </main>
    </div>
  );
};

export default CoursePlayer;
